def rpn(input):
	pre = {
		'!': 4,
		'>': 3, '<': 3, '=': 3, '@': 3,		# @ not equal
		'&': 2,
		'|': 1,
	}
	ret = []

	for line in input:
		if not re.search(r'^[IFF]', line):
			ret.append(line)
			continue

		out = []
		stack = []
		tokens = re.findall(r'[a-zA-Z0-9]+|!|[><=@&|]+', line)

		for token in tokens:
			if re.match(r'[a-zA-Z0-9]+', token):
				out.append(token)
			else:
				while (stack and pre.get(token, 0) <= pre.get(stack[-1], 0)):
					out.append(stack.pop())

				stack.append(token)

		while stack:
			out.append(stack.pop())

		ret.append(" ".join(out))

	return ret

